export const inlineScript = "\n  function confirmBonusRule() {\n    const card = document.getElementById('uncertainty-card');\n    const confirmedRow = document.getElementById('confirmed-bonus-row');\n    if (card) {\n      card.classList.add('opacity-0', 'scale-95');\n      setTimeout(() => {\n        card.style.display = 'none';\n        if (confirmedRow) {\n          confirmedRow.classList.remove('hidden');\n        }\n      }, 200);\n    }\n  }\n\n  function promptEditRule() {\n    const newVal = prompt(\"Enter customized points for 40+ yard TD bonus:\", \"+2.0\");\n    if (newVal !== null && newVal.trim() !== \"\") {\n      const display = document.getElementById('bonus-val-display');\n      if (display) {\n        display.innerText = newVal.startsWith('+') ? newVal + \" pts\" : \"+\" + newVal + \" pts\";\n      }\n      confirmBonusRule();\n    }\n  }\n\n  function addCustomRuleModal() {\n    const ruleName = prompt(\"Enter rule metric name (e.g., Fumble Lost, 2-Pt Conversion):\");\n    if (ruleName) {\n      alert(\"Custom rule '\" + ruleName + \"' added to queue.\");\n    }\n  }\n\n  function resetToStandard() {\n    if (confirm(\"Reset all detected points to standard Half-PPR NFL default?\")) {\n      alert(\"Reverted to NFL standard defaults.\");\n    }\n  }\n\n  function completeReview() {\n    alert(\"Scoring profile verified! Synchronizing league rosters...\");\n  }\n";
